import type { ZimmSizeChipValue } from '../../molecules/zimmSizeChipGroup';

/**
 * Shared Storybook/test fixture data for the ZimmProductCard family (SFCC-236). Extracted
 * because zimmProductCardMedia/index.stories.tsx, zimmProductCard/index.stories.tsx, and
 * zimmProductCard/nodeCoverage/index.stories.tsx each independently retyped byte-identical
 * values. Storybook/test fixture data only — not consumed by any production runtime path, so it
 * is fine for this to live co-located with the organism even though it is cross-molecule; see
 * .claude/rules/overrideStyling.md's "The SFCC bridge pattern" note on Storybook fixtures not
 * carrying the same "which component owns this DOM contract" concern real component code does.
 */

